contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(address _caller, address _recipient) public {
        require(_caller != c.owner());
        bool reverted = false;
        // probe via a static check is not possible; use try-less approach:
        // call withdrawAll as _caller is impossible (msg.sender fixed),
        // so instead verify by attempting with actual caller: if this test contract
        // is not owner, the call must revert.
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.withdrawAll.selector, _recipient));
        reverted = !ok;
        assert(reverted);
    }
    receive() external payable {}
    fallback() external payable {}
}

