contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function test(address _recipient, uint256 amount) public {
        require(address(this).balance >= amount);

        // Fund c through its fallback
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        // Only the owner may withdraw
        require(msg.sender == c.owner());

        uint256 balBefore = address(this).balance;

        // Owner withdraws everything to a third-party recipient
        c.withdrawAll(_recipient);

        // The owner/caller must not have received the funds
        assert(address(this).balance == balBefore);
    }
}

