contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // NOTE: this test contract intentionally has NO receive()/payable fallback,
    // so address(this) cannot accept Ether via transfer().
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        (bool sentOk, ) = address(c).call{value: amount}("");
        require(sentOk);
        bool reverted;
        try c.withdrawAll(address(this)) { reverted = false; } catch { reverted = true; }
        // Rule: withdrawAll( _recipient ) forwards the full balance to _recipient.
        // Since address(this) refuses Ether, the call must revert in P.
        // In M the funds go to the owner instead, so it would complete.
        assert(reverted);
    }
}

