contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address recipient) public {
        require(caller != address(this));
        c = c; // keep c in scope
        // caller is a parameter; we simulate a call by a non-owner by checking the owner getter
        address ownerAddr = c.owner();
        bool reverted;
        if (caller != ownerAddr) {
            // must be top-level plain call: use try at top level
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(reverted);
        } else {
            try c.withdrawAll(recipient) { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        }
    }
    receive() external payable {}
}

